-- Runtime-only local compatibility entry. The installed APK is unchanged.
local server=CS.Restifizer.RestifizerManager.Instance.AccountServerUrl
assert(server and server:match('^http://127%.0%.0%.1:19080/?$'), 'Local account server must be selected')
-- The server binds the guest account to the opaque device key carried by
-- AccountSession.  Do not embed an entry generated by an earlier run here:
-- after a clean install or a device rebind, that stale entry makes Auth
-- reject the otherwise valid session with ``guest entry is not registered``.
local window=CS.UIWindowManager.Instance:FindWindow('Login')
local env=window:GetComponent(typeof(CS.LuaInjector)).Sandbox
local WU,REF
for i=1,30 do
  local name,value=debug.getupvalue(env.SetupWindow,i)
  if not name then break end
  if name=='WU' then WU=value elseif name=='REF' then REF=value end
end
assert(WU and REF,'Login UI references unavailable')

-- Story-balance in the original client stores "ChapterNormal" as its return
-- window.  In the local build that opens normal chapter 1, whose stages are
-- intentionally not implemented.  Install the redirect once during login so
-- both the normal tutorial path and -FirstBattle return to story chapter
-- 1001.  The chapter-id guard leaves ordinary chapters alone.
local storyWU=require('Common/WindowUtil')()
if storyWU and storyWU.__localStoryReturnPatched ~= true then
  local returnCity=storyWU.ReturnCity
  if type(returnCity)=='function' then
    storyWU.ReturnCity=function(windowParam)
      local chapterId=CS.DataBindingManager.Instance:GetData('WindowDungeon/ChapterId')
      if windowParam=='ChapterNormal' and chapterId==1001 then
        storyWU.__localStoryReturnPatched=false
        return returnCity('ChapterNormal, DungeonStory')
      end
      return returnCity(windowParam)
    end
    storyWU.__localStoryReturnPatched=true
  end
end

-- RestfulResponse balance payloads are raw JSON, so the JSON decoder keeps
-- protobuf map keys such as `2012` as strings.  The stock story-balance Lua
-- expects the same recordDungeons map to have numeric keys (it indexes with
-- dungeonId).  The optional binding-level normalization is deliberately
-- disabled on this Android build because XLua aborts when a native C# method
-- is replaced from Lua; keep the login seam independent of that probe.
local numericChapterMapPatch=false
-- Do not assign ``dataBinding.SetData`` here.  XLua exposes this member as a
-- native C# method; replacing it from Lua invokes the binding's abort path on
-- the Android build (pcall cannot catch that native abort).  The local login
-- path must remain usable even when the optional chapter-map normalization is
-- unavailable, so the server keeps its typed chapter response and this probe
-- reports the patch as disabled.

-- The Android 11 x86 media service crashes in MediaPlayer.setDataSource when
-- the retired server's city-scene music is requested.  Return no scene audio
-- config so the stock City Lua skips PlayMusic entirely.  This keeps the
-- visual scene data available through PB.all while avoiding the emulator's
-- native media crash; it changes audio only and does not alter gameplay or
-- the protection path.
local pbHelper=require('Common/PbHelper')
if pbHelper and pbHelper.__localAudioCompat~=true and type(pbHelper.get)=='function' then
  local originalPbGet=pbHelper.get
  pbHelper.get=function(tableName,...)
    local value=originalPbGet(tableName,...)
    if tableName=='CollectionsScenes' and type(value)=='table' then
      return nil
    end
    return value
  end
  pbHelper.__localAudioCompat=true
end

-- The Android build unconditionally synchronizes Tencent billing on login.
-- Local guest accounts have no billing session; leave billing unavailable.
local S=require('Common/Singleton')
local iap=S:Get('IAPHandler')
local function isLocalGuest()
  -- This function is installed from the Login Lua environment, but it may be
  -- called later by PushService after that window has been recycled.  Read
  -- global account state instead of capturing Login's `env`/`this`.
  local manager=CS.Restifizer.RestifizerManager.Instance
  if manager==nil then return false end
  local url=manager.AccountServerUrl
  if type(url)~='string' or not url:match('^http://127%.0%.0%.1:19080/?$') then return false end
  if iap.__localGuestAttempt==true then return true end
  local dataManager=CS.DataBindingManager.Instance
  if dataManager==nil then return false end
  local cache=dataManager:GetData('accountCache')
  -- The marker is set by the local guest button before GuestSignup/Auth.
  -- It avoids depending on accountCache's asynchronous update ordering.
  return cache~=nil and cache.entryType=='guest'
end
if not iap.__localGuestBillingGuard then
  local sync=iap.SyncMidas
  iap.SyncMidas=function(callback)
    if isLocalGuest() then
      if callback then callback(nil) end
      return
    end
    return sync(callback)
  end
  iap.__localGuestBillingGuard=true
end

-- Keep the stock Midas module intact while installing the optional local
-- sandbox purchase seam.  The helper is runtime-only and may be absent when
-- this entry is evaluated from an unmodified APK; in that case the normal
-- client purchase function remains available and no native code is touched.
local sandboxIapOk,sandboxIap=pcall(require,'local-sandbox-iap')
if sandboxIapOk and sandboxIap then
  local install=sandboxIap.install or sandboxIap
  if type(install)=='function' then
    pcall(install,iap)
  end
end

-- The stock login callback can recycle the Login window's data table before
-- PushService handles ScLoginBegin.  That leaves socialEntry nil for the
-- telemetry-only TssSdk call even though this is a local guest account.  The
-- listener is registered by LoginPushBegin after this script runs, so wrap
-- the module callback now and restore harmless non-null telemetry values just
-- before the original handler reads accountCache.  This does not replace any
-- native C# method.
local pushService=S:Get('PushService')
if pushService and pushService.__localGuestTssGuard~=true then
  local onLoginBegin=pushService.OnScLoginBegin
  if type(onLoginBegin)=='function' then
    pushService.OnScLoginBegin=function(pushData)
      local dataManager=CS.DataBindingManager.Instance
      local cache=dataManager:GetData('accountCache') or {}
      local manager=CS.Restifizer.RestifizerManager.Instance
      local url=manager and manager.AccountServerUrl
      if type(url)=='string' and url:match('^http://127%.0%.0%.1:19080/?$') then
        cache.socialEntry=cache.socialEntry or 'local_guest'
        cache.socialPlatform=cache.socialPlatform or 0
        dataManager:SetData('accountCache',cache)
      end
      return onLoginBegin(pushData)
    end
    pushService.__localGuestTssGuard=true
  end
end

local button=REF.LoginButtons[0]['$']
button.UISprite.spriteName='guest_button'
button.UISprite:MakePixelPerfect()
button.gameObject:SetActive(true)
WU.BindButtonEvent(button,function()
  if not env.canAuthLogin() then return end
  local preferences=require('Common/Singleton'):Get('ConfigDataManager').GetPreferences()
  if not preferences.isAcceptLicense then env.ShowLicenseNotAgree(); return end
  -- Mark the local flow before any async AccountSession/PushService work.
  -- The marker lives on the singleton, not in the Login window environment.
  iap.__localGuestAttempt=true
  local account=env.this:GetData('accountCache') or {}
  -- Keep the account explicitly local while the stock GuestSignup flow
  -- obtains the current device-bound entry and refreshes its access token.
  account.entryType='guest'
  account.accountEntry=nil
  -- PushService.OnScLoginBegin forwards these two fields to TssSdk.  The
  -- original guest endpoint never supplied social credentials, which leaves
  -- socialEntry nil and crashes the old Android TSS wrapper when it calls
  -- Encoding.GetBytes.  Keep the account explicitly local while providing
  -- harmless non-null placeholders for that telemetry-only call.
  if account.socialEntry==nil or account.socialEntry=='' then
    account.socialEntry='local_guest'
  end
  if account.socialPlatform==nil then account.socialPlatform=0 end
  env.this:SetData('accountCache',account)
  -- GuestSignup performs AccountSession -> EntryReg -> Account -> Auth.
  -- The returned entry is authoritative and remains stable through the
  -- server's device binding, so it works for both a new install and a
  -- relaunch after the original client has crashed.
  env.GuestSignup()
end)
WU.DivideAlign({button},1500)
env.ShowAroundWidget()
return 'Persistent local account button enabled; guest-compatible protocol uses localhost; numeric chapter map patch=' .. tostring(numericChapterMapPatch)
